import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as i}from"./chunks/DIS.DdpTdGGD.js";import{_ as a,o,c as s,a3 as n}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Li3","description":"","frontmatter":{},"headers":[],"relativePath":"install/li3.md","filePath":"install/li3.md"}'),r={name:"install/li3.md"};function l(d,t,c,p,h,u){return o(),s("div",null,[...t[0]||(t[0]=[n('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  Hardware Data Source<br>   Li3</p></div><p>The Li3 data source, added in release <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer">2026.11.21</a>, connects xDrip directly to a Li3 device. You can also select it with the <a href="./datasource.html">Source wizard</a> in the Libre group.</p><p>xDrip starts a new session, or takes over a session in progress, with an NFC scan. It then receives readings by Bluetooth.</p><ul><li>Readings arrive every 5 minutes, or every minute if <a href="./../use/misc.html">Libre one minute</a> is enabled.</li><li>When the connection comes back after a gap, xDrip fills in the missing readings from the device history. Readings already stored are never replaced.</li><li><strong>This data source cannot be calibrated.</strong> If you try, xDrip shows <em>This sensor cannot be calibrated.</em></li></ul><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>When xDrip starts or takes over a session, the official app stops getting its readings and alarms.</p></div><br><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Your phone must have NFC. Without NFC, xDrip shows <em>This phone has no NFC, so it cannot start a Li3.</em></li><li>Turn on NFC in the phone settings. xDrip offers to turn on its own NFC scanning if it is off.</li><li>xDrip needs the location permission, and location must be on, to scan for the device by Bluetooth. The Li3 screen asks for whatever is missing.</li><li>You need an internet connection once, to download the app credential.</li><li>If you haven&#39;t yet, <a href="./install.html#make-sure-xdrip-will-not-be-put-to-sleep">check xDrip will not be put to sleep</a>.</li></ul><br><h2 id="the-li3-screen" tabindex="-1">The Li3 screen <a class="header-anchor" href="#the-li3-screen" aria-label="Permalink to &quot;The Li3 screen&quot;">​</a></h2><p>The Li3 screen lists the setup steps, shows how far you got, and reads NFC scans while it is open.<br> It opens by itself when you select the Li3 data source, and when you tap Start Sensor while no sensor is started. You can also open it from System Status:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> System Status<br>  Li3 Status<br>   Li3  Open</p></div><p>Until the setup is finished, xDrip also shows a notification that opens this screen: <em>Li3 setup not finished; open System Status, Li3</em>.</p><p>If you scan the device while another screen is open, xDrip opens the Li3 screen and asks you to scan again there: <em>Scan the device again on the Li3 screen to start it or take it over</em>.</p><br><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><h4 id="1-download-the-app-credential" tabindex="-1">1. Download the app credential <a class="header-anchor" href="#1-download-the-app-credential" aria-label="Permalink to &quot;1. Download the app credential&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  DOWNLOAD APP CREDENTIAL </div></p></div><p>The device pairs with an app credential. If none is downloaded yet, xDrip offers to download it when you open the Li3 screen.<br> When it&#39;s done, the App credential line under the buttons shows <em>Downloaded</em>. If the download fails, check your internet connection and tap Download again.</p><h4 id="2-account-id-only-to-take-over-a-session-started-by-an-official-app" tabindex="-1">2. Account ID (only to take over a session started by an official app) <a class="header-anchor" href="#2-account-id-only-to-take-over-a-session-started-by-an-official-app" aria-label="Permalink to &quot;2. Account ID (only to take over a session started by an official app)&quot;">​</a></h4><p>Skip this step to start a new session for xDrip.</p><p>To take over a session that an official app started, xDrip needs that app&#39;s account ID.</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  LOOK UP ACCOUNT ID </div></p></div><p>Log in with the account that started the session, not a follower account. xDrip keeps only the account ID, not the email or password.<br> If the login is refused because of new terms, open the official app with this account, accept the terms, then try again.<br> If the lookup fails, you can enter the account ID yourself in the <a href="#li3-settings">Li3 settings</a>.</p><p>Then choose the app that started the session:</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  SENSOR APP: LI3 APP </div></p></div><div class="admonition xdripitem"><p class="admonition-title">Which app started this session?</p><p> Li3 app<br>  Multi-sensor app</p></div><h4 id="3-scan-the-device" tabindex="-1">3. Scan the device <a class="header-anchor" href="#3-scan-the-device" aria-label="Permalink to &quot;3. Scan the device&quot;">​</a></h4><p>With the Li3 screen open, scan the device with your phone. xDrip asks one of these questions:</p><table tabindex="0"><thead><tr><th>Device</th><th>Account ID set</th><th>No account ID</th></tr></thead><tbody><tr><td>New</td><td><strong>Start Sensor</strong>: xDrip gets the readings. The official app can take the device back later with the same account.</td><td><strong>Start Sensor</strong>: the session is for xDrip on this phone only. <strong>The device can never move to an official app, and is lost if xDrip is reinstalled.</strong></td></tr><tr><td>Session in progress</td><td><strong>Take over Li3</strong>: the official app stops getting its readings and alarms.</td><td>Only works for a session started by xDrip on this phone. For a session started by an official app, look up its account ID first.</td></tr></tbody></table><p>Without an account ID, you can tap <em>Look up account ID</em>, or tap <em>Scan anyway</em> to go on without one.</p><p>Press OK, then <strong>scan the device again within five minutes</strong> to confirm.<br> When it works, xDrip shows <em>Li3 ready, connecting by Bluetooth</em>.</p><p>If the device refuses the command, check that the app and the account ID are the ones the session was started with.<br> If xDrip already uses this device, nothing is sent. To pair it again, tap Forget Device on the Li3 screen, then scan it.</p><h4 id="4-wait-for-the-first-reading" tabindex="-1">4. Wait for the first reading <a class="header-anchor" href="#4-wait-for-the-first-reading" aria-label="Permalink to &quot;4. Wait for the first reading&quot;">​</a></h4><p>A new device sends no readings during its first hour or so.</p><br><h2 id="li3-settings" tabindex="-1">Li3 settings <a class="header-anchor" href="#li3-settings" aria-label="Permalink to &quot;Li3 settings&quot;">​</a></h2><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>   Less Common settings<br>    Other Misc. options<br>     Li3</p></div><div class="admonition xdripitem"><p class="admonition-title">Account ID</p><p> Needed to take over a session in progress. Leave empty to start a new session for xDrip on this phone only.</p></div><p>Look up account ID on the Li3 screen fills it in for you.</p><div class="admonition xdripitem"><p class="admonition-title">Official app</p><p> The app the account uses</p></div><p>Li3 app (default) or Multi-sensor app. This is the same choice as the Sensor app button on the Li3 screen.</p><div class="admonition xdripitem"><p class="admonition-title">Smooth Li3 readings <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Average recent readings to make them smoother</p></div><p>The NFC settings that don&#39;t apply to Li3 (sensor age, expiry days, multiblock, any tag, Libre 2 Bluetooth streaming) are hidden while Li3 is the data source.</p><br><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>The Li3 screen and System Status → Li3 Status show:</p><ul><li><strong>Device</strong></li><li><strong>Stage</strong>: what xDrip is doing now, for example: <ul><li><em>No device; scan one with NFC</em></li><li><em>No app credential; tap Download on the Li3 screen</em></li><li><em>Looking for the device; keep the phone near it</em></li><li><em>Lost the device; trying again soon</em></li><li><em>Connected; waiting for a reading</em></li><li><em>Session ended; scan a new device with NFC</em></li></ul></li><li><strong>Last error</strong></li><li><strong>Reading not stored</strong>, when xDrip refused a reading: no valid value, the session start time looks wrong, or the device marked the reading as unreliable</li><li><strong>Started</strong> and <strong>Sensor life</strong> (or <em>Expired</em>)</li><li><strong>Last reading</strong></li><li><strong>App credential</strong></li></ul><h4 id="forget-device" tabindex="-1">Forget Device <a class="header-anchor" href="#forget-device" aria-label="Permalink to &quot;Forget Device&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  FORGET DEVICE </div></p></div><p>xDrip stops talking to this device. To use it again, scan it with NFC.<br> A session started without an account can only come back to xDrip on this phone.</p><h4 id="copy-diagnostics" tabindex="-1">Copy diagnostics <a class="header-anchor" href="#copy-diagnostics" aria-label="Permalink to &quot;Copy diagnostics&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  COPY DIAGNOSTICS </div></p></div><p>Copies diagnostic information to the clipboard. Paste it when you ask for help.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 22/11/2026</em></a></p>',56)])])}const b=a(r,[["render",l]]);export{v as __pageData,b as default};
